AND     Trs_ProdExp.StyleNo =    Vue_OrdExcessQtyWitStyleClr.StyleNo LEFT OUTER JOIN (Select Distinct OrdID,Styleno,PartID,NWork,ClrID,JobWrkRate,Rate_Pcs From Bud_InhRateclw)   Bud_InhRateclw ON  Trs_ProdExp.OrdId = Bud_InhRateclw.OrdID AND  Trs_ProdExp.StyleNo = Bud_InhRateclw.Styleno AND   Trs_ProdExp.WrkID =  Bud_InhRateclw.NWork and Vue_OrdExcessQtyWitStyleClr.PartId = Bud_InhRateclw.PartId  And  /* 'Nasima Vue_OrdExcessQtyWitStyleClr.ColId =   Bud_InhRateclw.ClrID */ (1=Case When (Select IsNull(BudRt_CMT_Sizewise,'N') From Options)='N' and  Vue_OrdExcessQtyWitStyleClr.ColId=Bud_InhRateclw.ClrID Then 0 Else 1 End) LEFT OUTER JOIN Pro_Prod_PartwiseRate ON Trs_ProdExp.OrdId=Pro_Prod_PartwiseRate.OrdId And Trs_ProdExp.StyleNo=Pro_Prod_PartwiseRate.StyleNo And Trs_ProdExp.WrkID= Pro_Prod_PartwiseRate.WrkID cross join options  Where Mas_Dept.SEMIFINISH='F' And IsNull(Pro_Prod_PartwiseRate.PartId,0)<>0 And IsNull(Mas_JobWrkComp.ProdType,'C')='A') X GROUP BY X.GrpOrdID,X.OrdId, x.StyleNo,X.WorkComplDet, X.OrderSno,X.Grpslno,X.DeptID, X.PrsLossPercent,X.ColId 
