 * Bud_InhRateclw.Rate_Pcs), 0) else ISNULL(((Vue_OrdExcessQtyWitStyleClr1.orderQty/PcePerPack) * Bud_InhRateclw.Rate_Pcs), 0) end ELSE CASE WHEN   ISNULL(Bud_InhRateclw.JobWrkRate, 0)   > 0  THEN   case when isnull(Allow_excess_inbudget,'N')='Y' then ISNULL(((Vue_OrdExcessQtyWitStyleClr1.ExsQty/PcePerPack) *  Bud_InhRateclw.JobWrkRate), 0) else ISNULL(((Vue_OrdExcessQtyWitStyleClr1.orderqty/PcePerPack) * Bud_InhRateclw.JobWrkRate), 0)  end ELSE CASE WHEN   ISNULL(Pro_Prod_PartwiseRate.Rate, 0)   > 0  THEN   case when isnull (Allow_excess_inbudget,'N')='Y' then ISNULL(((Vue_OrdExcessQtyWitStyleClr.ExsQty/PcePerPack) * Pro_Prod_PartwiseRate.Rate), 0) else ISNULL(((Vue_OrdExcessQtyWitStyleClr.orderqty/PcePerPack) * Pro_Prod_PartwiseRate.Rate), 0)  end ELSE 
