ND Trs_ProdExp.StyleNo =   Vue_OrdExcessQtyWitStyleClr1.StyleNo And /* 'Nasima ' Bud_InhRateclw.ClrID = Vue_OrdExcessQtyWitStyleClr1.ColId */  (1=Case When (Select IsNull(BudRt_CMT_Sizewise,'N') From Options)='N' and Bud_InhRateclw.ClrID = Vue_OrdExcessQtyWitStyleClr1.ColId Then 0 Else 1 End) AND Vue_OrdExcessQtyWitStyleClr1.Partid=Vue_OrdExcessQtyWitStyleClr.PartId LEFT OUTER JOIN Pro_Prod_PartwiseRate ON Trs_ProdExp.OrdId=Pro_Prod_PartwiseRate.OrdId And Trs_ProdExp.StyleNo=Pro_Prod_PartwiseRate.StyleNo And Trs_ProdExp.WrkID=Pro_Prod_PartwiseRate.WrkID cross join options Where Mas_Dept.SEMIFINISH='F' And    IsNull(Pro_Prod_PartwiseRate.PartId,0)=0 And IsNull(Mas_JobWrkComp.ProdType,'C')='C') X GROUP BY X.GrpOrdID,X.OrdId,x.StyleNo, X.WorkComplDet, X.OrderSno,X.Grpslno,X.DeptID,X.PrsLossPercent,
  X.ColId   
