SELECT OrderMas.OrdID as GrpOrdID,   OrderMas.OrdId,''as Styleno, Mas_Commercial.Descr, PRo_BudCommercial.SlNo,  
 PRo_BudCommercial.Total AS Amount, 0 AS Expr1, 0 AS deptid,0 as PrsLossPercent,0 As ColId FROM  PRo_BudCommercial INNER JOIN  OrderMas ON  PRo_BudCommercial.OrdID = OrderMas.OrdId INNER JOIN  Mas_Commercial ON PRo_BudCommercial.ComID = Mas_Commercial.ID 
INNER JOIN  Vue_Rpt_OrdExcessQty ON OrderMas.OrdId = Vue_Rpt_OrdExcessQty.OrdID INNER JOIN Vue_Rpt_OrdQtywithSaleRate ON OrderMas.OrdId =  Vue_Rpt_OrdQtywithSaleRate.OrdID cross join  options    union all  /* For fabric Module  */SELECT  OrderMas.OrdID as
 GrpOrdID,   OrderMas.OrdId,''as Styleno, Mas_Commercial.Descr, PRo_BudCommercial.SlNo, CASE WHEN per >  0 THEN (Vue_Rpt_OrdExcessQty_Fabric.salesamt * crate) * per / 100 WHEN val > 0 THEN Vue_Rpt_OrdExcessQty_Fabric.qty * Val  ELSE Total END AS Amount, 0 AS Expr1, 0 AS deptid,0 as PrsLossPercent,0 As ColId FROM PRo_BudCommercial INNER JOIN  OrderMas ON  PRo_BudCommercial.OrdID = OrderMas.OrdId INNER JOIN  Mas_Commercial ON PRo_BudCommercial.ComID = Mas_Commercial.ID  INNER JOIN Vue_Rpt_OrdExcessQty_Fabric ON OrderMas.OrdId = Vue_Rpt_OrdExcessQty_Fabric.OrdID 